/* The rotated display setups provide no software cursor: they leave the
   capture, restore, draw, position set and enable functions NULL and keep
   the generic define. On a display made by each of the four (24xrgb, 32argb,
   565rgb and 8-bit palette, rotated), a cursor can be defined but not shown
   or hidden, and a pen move or a pen down over its root window leaves the
   cursor position and the canvas as they were. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_mouse_cursor_rotated_display_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_WIDTH  64
#define TEST_HEIGHT 48
#define TEST_RUNS   4

UINT gx_validation_graphics_driver_setup_24xrgb_rotated(GX_DISPLAY *display);
UINT gx_validation_graphics_driver_setup_32argb_rotated(GX_DISPLAY *display);
UINT gx_validation_graphics_driver_setup_565rgb_rotated(GX_DISPLAY *display);
UINT gx_validation_graphics_driver_setup_8bit_palette_rotated(GX_DISPLAY *display);

static UINT           failed_tests = 0;

static TX_THREAD      test_thread;
static ULONG          test_thread_stack[4096 / sizeof(ULONG)];

static GX_DISPLAY     test_displays[TEST_RUNS];
static GX_CANVAS      test_canvases[TEST_RUNS];
static GX_WINDOW_ROOT test_roots[TEST_RUNS];

/* Room for the widest pixel; each canvas uses what its format needs.  */
static ULONG          test_canvas_memory[TEST_WIDTH * TEST_HEIGHT];
static GX_UBYTE       test_canvas_copy[sizeof(test_canvas_memory)];

static GX_PIXELMAP    test_cursor_map;
static GX_PIXELMAP   *test_pixelmap_table[2] = {GX_NULL, &test_cursor_map};
static GX_MOUSE_CURSOR_INFO test_cursor = {1, 0, 0};

static VOID test_pen(INT type, GX_VALUE x, GX_VALUE y)
{
GX_EVENT event;

    memset(&event, 0, sizeof(GX_EVENT));
    event.gx_event_type = (GX_UBYTE)type;
    event.gx_event_display_handle = 1;
    event.gx_event_payload.gx_event_pointdata.gx_point_x = x;
    event.gx_event_payload.gx_event_pointdata.gx_point_y = y;
    _gx_system_event_dispatch(&event);
}

static VOID test_rotated(INT run, char *name, UINT (*setup)(GX_DISPLAY *))
{
UINT            status;
INT             index;
GX_RECTANGLE    size;
GX_POINT        pos;
GX_DISPLAY     *display = &test_displays[run];
GX_CANVAS      *canvas = &test_canvases[run];
GX_WINDOW_ROOT *root = &test_roots[run];

    status = gx_display_create(display, name, setup, TEST_WIDTH, TEST_HEIGHT);
    EXPECT_EQ(GX_SUCCESS, status);
    EXPECT_EQ(GX_TRUE, display -> gx_display_rotation_angle != GX_SCREEN_ROTATION_NONE);

    /* No software cursor; the generic define is kept.  */
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_capture == GX_NULL);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_restore == GX_NULL);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_draw == GX_NULL);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_position_set == GX_NULL);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_enable == GX_NULL);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse_define != GX_NULL);

    status = gx_display_pixelmap_table_set(display, test_pixelmap_table, 2);
    EXPECT_EQ(GX_SUCCESS, status);
    status = gx_canvas_create(canvas, name, display, GX_CANVAS_SIMPLE, TEST_WIDTH, TEST_HEIGHT,
                              (GX_COLOR *)test_canvas_memory, sizeof(test_canvas_memory));
    EXPECT_EQ(GX_SUCCESS, status);
    gx_utility_rectangle_define(&size, 0, 0, TEST_WIDTH - 1, TEST_HEIGHT - 1);
    status = gx_window_root_create(root, name, canvas, GX_STYLE_BORDER_NONE, GX_NULL, &size);
    EXPECT_EQ(GX_SUCCESS, status);
    EXPECT_EQ(GX_SUCCESS, gx_widget_show(root));

    for (index = 0; index < (INT)sizeof(test_canvas_memory); index++)
    {
        ((GX_UBYTE *)test_canvas_memory)[index] = (GX_UBYTE)(index * 7 + run);
    }
    memcpy(test_canvas_copy, test_canvas_memory, sizeof(test_canvas_memory));
    pos = display -> gx_display_mouse.gx_mouse_position;

    /* Defined, but neither shown nor hidden.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_mouse_define(canvas, &test_cursor));
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse.gx_mouse_cursor_info == &test_cursor);
    EXPECT_EQ(GX_TRUE, display -> gx_display_mouse.gx_mouse_canvas == canvas);
    EXPECT_EQ(GX_FAILURE, gx_canvas_mouse_show(canvas));
    EXPECT_EQ(GX_FAILURE, gx_canvas_mouse_hide(canvas));

    /* The pen over the root window does not move a cursor.  */
    test_pen(GX_EVENT_PEN_MOVE, 10, 12);
    test_pen(GX_EVENT_PEN_DOWN, 20, 22);
    test_pen(GX_EVENT_PEN_UP, 20, 22);
    EXPECT_EQ(pos.gx_point_x, display -> gx_display_mouse.gx_mouse_position.gx_point_x);
    EXPECT_EQ(pos.gx_point_y, display -> gx_display_mouse.gx_mouse_position.gx_point_y);
    EXPECT_EQ(0, display -> gx_display_mouse.gx_mouse_status);
    EXPECT_EQ(0, memcmp(test_canvas_copy, test_canvas_memory, sizeof(test_canvas_memory)));

    /* Out of the way of the next run's pen events.  */
    EXPECT_EQ(GX_SUCCESS, gx_widget_hide(root));
}

static VOID test_thread_entry(ULONG id)
{
    gx_system_initialize();

    memset(&test_cursor_map, 0, sizeof(GX_PIXELMAP));
    test_cursor_map.gx_pixelmap_width = 4;
    test_cursor_map.gx_pixelmap_height = 4;

    test_rotated(0, "24xrgb_rotated", gx_validation_graphics_driver_setup_24xrgb_rotated);
    test_rotated(1, "32argb_rotated", gx_validation_graphics_driver_setup_32argb_rotated);
    test_rotated(2, "565rgb_rotated", gx_validation_graphics_driver_setup_565rgb_rotated);
    test_rotated(3, "8bit_palette_rotated", gx_validation_graphics_driver_setup_8bit_palette_rotated);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

